	start := time.Now()
	for i := 0; i < *connections; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			worker(i, c, target, payload, *sendChunk, linger, results)
		}(i)
	}

	wg.Wait()
	fmt.Printf("[*] elapsed=%s\n", time.Since(start).Round(time.Millisecond))
